ipc_watcher, ipc_notifier = multiprocessing.Pipe()


def notice(msg):
    syslog.syslog(syslog.LOG_NOTICE, msg)


def end(res, exit_msg):
    if res is not None:
        print(json.dumps(res))
        sys.stdout.flush()
    sys.exit(exit_msg)


def jwrite(info):
    try:
        with open(job_path + ".tmp", "w") as jobfile:
            json.dump(info, jobfile)
        os.rename(job_path + ".tmp", job_path)
    except Exception as e:
        notice("Could not write job result: %s" % to_text(e))
