def daemonize_self():
    # daemonizing code: http://aspn.activestate.com/ASPN/Cookbook/Python/Recipe/66012
    try:
        pid = os.fork()
        if pid > 0:
            # exit first parent
            end(None, 0)
    except OSError:
        e = sys.exc_info()[1]
        end({"failed": True, "msg": "fork #1 failed: %s" % to_text(e), "ansible_job_id": jid}, 1)

    # decouple from parent environment (does not chdir / to keep the directory context the same as for non async tasks)
    os.setsid()
    os.umask(int('022', 8))

    # do second fork
    try:
        pid = os.fork()
        if pid > 0:
            # print "Daemon PID %d" % pid
            end(None, 0)
    except OSError:
        e = sys.exc_info()[1]
        jwrite({"started": 1, "finished": 1, "failed": True, "msg": "fork #2 failed: %s" % to_text(e), "ansible_job_id": jid})
        end(None, 1)

    dev_null = open('/dev/null', 'w')
    os.dup2(dev_null.fileno(), sys.stdin.fileno())
    os.dup2(dev_null.fileno(), sys.stdout.fileno())
    os.dup2(dev_null.fileno(), sys.stderr.fileno())

